package com.rodrigosambade.offlinefirst; import android.app.*;import android.os.*;import android.widget.*;import androidx.work.*;import java.util.*;import java.util.concurrent.*;public class MainActivity extends Activity{EditText input;TextView list;ExecutorService io=Executors.newSingleThreadExecutor();@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,32,32,32);input=new EditText(this);input.setHint("Offline note");l.addView(input);Button add=new Button(this);add.setText("Save locally");add.setOnClickListener(v->save());l.addView(add);Button sync=new Button(this);sync.setText("Enqueue network sync");sync.setOnClickListener(v->enqueue());l.addView(sync);list=new TextView(this);l.addView(list);setContentView(l);refresh();}void save(){String s=input.getText().toString().trim();if(s.isEmpty())return;io.execute(()->{AppDatabase.get(this).notes().insert(new NoteEntity(s,false,System.currentTimeMillis()));runOnUiThread(()->{input.setText("");refresh();});});}void enqueue(){Constraints c=new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build();OneTimeWorkRequest r=new OneTimeWorkRequest.Builder(SyncWorker.class).setConstraints(c).build();WorkManager.getInstance(this).enqueueUniqueWork("notes-sync",ExistingWorkPolicy.REPLACE,r);Toast.makeText(this,"Sync queued",Toast.LENGTH_SHORT).show();}void refresh(){io.execute(()->{List<NoteEntity> ns=AppDatabase.get(this).notes().all();StringBuilder b=new StringBuilder();for(NoteEntity n:ns)b.append(n.synced?"✓ ":"⏳ ").append(n.text).append('\n');runOnUiThread(()->list.setText(b.toString()));});}@Override protected void onDestroy(){super.onDestroy();io.shutdown();}}